package com.innovatus.studentrecords.service; import com.innovatus.studentrecords.config.EmailConfig; import jakarta.mail.*; import jakarta.mail.internet.*; import java.nio.file.Path; import java.util.*;
public class EmailService {private Session session(){Properties p=new Properties();p.put("mail.smtp.auth","true");p.put("mail.smtp.starttls.enable","true");p.put("mail.smtp.host",EmailConfig.host());p.put("mail.smtp.port",String.valueOf(EmailConfig.port()));return Session.getInstance(p,new Authenticator(){protected PasswordAuthentication getPasswordAuthentication(){return new PasswordAuthentication(EmailConfig.username(),EmailConfig.appPassword());}});} public void otp(String to,String code)throws MessagingException{send(to,"Student Records password reset","Your verification code is "+code+". It expires in 5 minutes.",null);} public void export(String to,Path file)throws MessagingException{send(to,"Your student records export","Your requested filtered export is attached.",file);} private void send(String to,String subject,String body,Path file)throws MessagingException{if(EmailConfig.username().isBlank()||EmailConfig.appPassword().isBlank())throw new MessagingException("SMTP credentials are not configured.");MimeMessage m=new MimeMessage(session());m.setFrom(new InternetAddress(EmailConfig.username()));m.setRecipients(Message.RecipientType.TO,to);m.setSubject(subject);MimeMultipart mp=new MimeMultipart();MimeBodyPart text=new MimeBodyPart();text.setText(body);mp.addBodyPart(text);if(file!=null){MimeBodyPart a=new MimeBodyPart();try{a.attachFile(file.toFile());}catch(java.io.IOException e){throw new MessagingException("Could not attach export",e);}mp.addBodyPart(a);}m.setContent(mp);Transport.send(m);}}
